using CallingBell.Api.Data;using CallingBell.Api.Models;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace CallingBell.Api.Controllers;[ApiController][Route("api/v1/dashboard")]public sealed class DashboardController(CallingBellDbContext db):ControllerBase{[HttpGet]public async Task<ActionResult<ApiResponse<DashboardDto>>> Get(CancellationToken ct){var b=await db.Banners.AsNoTracking().Where(x=>x.IsActive).OrderByDescending(x=>x.Id).FirstOrDefaultAsync(ct);var c=await db.Categories.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.Id).Take(12).ToListAsync(ct);var bs=await db.Businesses.AsNoTracking().Where(x=>x.IsActive).OrderByDescending(x=>x.IsSponsored).ThenByDescending(x=>x.Rating).Take(8).ToListAsync(ct);var t=await db.TrendingServices.AsNoTracking().Where(x=>x.IsActive).OrderByDescending(x=>x.Searches).Take(5).ToListAsync(ct);var n=await db.NearbyBusinesses.AsNoTracking().OrderBy(x=>x.DistanceKm).Take(6).ToListAsync(ct);var d=new DashboardDto{Banner=b is null?null:new BannerDto(b.Id,b.Title,b.Subtitle,b.ImageUrl,b.CtaText),Categories=c.Select(x=>new CategoryDto(x.Id,x.Name,x.Icon,x.BusinessCount)).ToList(),FeaturedBusinesses=bs.Select(x=>new BusinessDto(x.Id,x.Name,x.Category,x.ImageUrl,x.Rating,x.ReviewCount,x.DistanceKm,x.IsVerified,x.IsSponsored,x.Address)).ToList(),TrendingServices=t.Select(x=>new TrendingServiceDto(x.Id,x.Name,x.Searches,x.ImageUrl)).ToList(),NearbyBusinesses=n.Select(x=>new NearbyBusinessDto(x.Id,x.Name,x.Category,x.DistanceKm)).ToList()};return Ok(new ApiResponse<DashboardDto>(true,"Dashboard retrieved successfully.",d,[]));}}